287	    /** 原子写入封榜快照头表、全部条目以及每名选手的分段明细。 */
288	    public void insertSnapshot(SnapshotRow snapshot) {
289	        jdbcTemplate.update(
290	                "INSERT INTO result_snapshot (race_id, version, sealed_at) VALUES (?, ?, ?)",
291	                snapshot.raceId(), snapshot.version(), snapshot.sealedAt());
292	        jdbcTemplate.batchUpdate(
293	                "INSERT INTO result_snapshot_entry "
294	                        + "(race_id, bib, rank_no, status, finish_time_ms, penalty_ms, total_time_ms, "
295	                        + "display_order, checkpoint_count, covered_checkpoint_count) "
296	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
297	                snapshot.entries(),
298	                snapshot.entries().size(),
299	                (ps, entry) -> {
300	                    ps.setString(1, entry.raceId());
301	                    ps.setString(2, entry.bib());
302	                    ps.setObject(3, entry.rank());
303	                    ps.setString(4, entry.status().name());
304	                    ps.setObject(5, entry.finishTimeMs());
305	                    ps.setLong(6, entry.penaltyMs());
306	                    ps.setObject(7, entry.totalTimeMs());
307	                    ps.setInt(8, entry.displayOrder());
308	                    ps.setInt(9, entry.checkpointCount());
309	                    ps.setInt(10, entry.coveredCheckpointCount());
310	                });
311	        jdbcTemplate.batchUpdate(
312	                "INSERT INTO result_snapshot_checkpoint "
313	                        + "(race_id, bib, checkpoint_code, position, elapsed_millis, timing_id) "
314	                        + "VALUES (?, ?, ?, ?, ?, ?)",
315	                snapshot.checkpoints(),
316	                snapshot.checkpoints().size(),
317	                (ps, detail) -> {
318	                    ps.setString(1, detail.raceId());
319	                    ps.setString(2, detail.bib());
320	                    ps.setString(3, detail.checkpointCode());
321	                    ps.setInt(4, detail.position());
322	                    ps.setObject(5, detail.elapsedMillis());
323	                    ps.setString(6, detail.timingId());
324	                });
325	    }
326	
327	    /** 按请求ID查询幂等记录。 */
328	    public Optional<IdempotencyRow> findIdempotency(String requestId) {
329	        return jdbcTemplate
330	                .query("SELECT request_id, operation, request_digest, response_status, response_body, created_at "
331	                                + "FROM idempotency_record WHERE request_id = ?",
332	                        IDEMPOTENCY_ROW_MAPPER, requestId)
333	                .stream()
334	                .findFirst();
335	    }
336	
337	    /**
338	     * 插入幂等占位行（response_status=0 表示进行中），同事务失败回滚即不占键。
339	     * 并发同键时由唯一约束拒绝，调用方再通过 {@link #findIdempotencyForUpdate} 等待先行者结束。
340	     */
341	    public void insertIdempotencyPlaceholder(
342	            String requestId, String operation, String requestDigest, long now) {
343	        jdbcTemplate.update(
344	                "INSERT INTO idempotency_record "
345	                        + "(request_id, operation, request_digest, response_status, response_body, created_at) "
346	                        + "VALUES (?, ?, ?, 0, '', ?)",
347	                requestId, operation, requestDigest, now);
348	    }
349	
350	    /**
351	     * 行锁方式查询幂等记录：若先行者事务未结束则阻塞至其提交或回滚；
352	     * 回滚后占位行随事务消失，返回 empty，调用方可重新占位执行。
353	     */
354	    public Optional<IdempotencyRow> findIdempotencyForUpdate(String requestId) {
355	        return jdbcTemplate
356	                .query("SELECT request_id, operation, request_digest, response_status, response_body, created_at "
357	                                + "FROM idempotency_record WHERE request_id = ? FOR UPDATE",
358	                        IDEMPOTENCY_ROW_MAPPER, requestId)
359	                .stream()
360	                .findFirst();
361	    }
362	
363	    /** 业务成功后把占位行补写为最终响应，与业务变更同事务原子提交。 */
364	    public void completeIdempotency(String requestId, int responseStatus, String responseBody) {
365	        jdbcTemplate.update(
366	                "UPDATE idempotency_record SET response_status = ?, response_body = ? "
367	                        + "WHERE request_id = ?",
368	                responseStatus, responseBody, requestId);
369	    }
370	
371	    /** 测试辅助：清空全部业务数据，按外键依赖顺序删除。 */
372	    public void deleteAllForTesting() {
373	        jdbcTemplate.update("DELETE FROM result_snapshot_checkpoint");
374	        jdbcTemplate.update("DELETE FROM result_snapshot_entry");
375	        jdbcTemplate.update("DELETE FROM result_snapshot");
376	        jdbcTemplate.update("DELETE FROM idempotency_record");
377	        jdbcTemplate.update("DELETE FROM checkpoint_timing");
378	        jdbcTemplate.update("DELETE FROM checkpoint");
379	        jdbcTemplate.update("DELETE FROM penalty");
380	        jdbcTemplate.update("DELETE FROM runner");
381	        jdbcTemplate.update("DELETE FROM race");
382	    }
383	
384	    private static final class RaceRowMapper implements RowMapper<RaceRow> {
385	        @Override
386	        public RaceRow mapRow(ResultSet rs, int rowNum) throws SQLException {
387	            return new RaceRow(
388	                    rs.getString("race_id"),
