1	package com.example.starter.race.service;
2	
3	import com.example.starter.race.api.AddPenaltyRequest;
4	import com.example.starter.race.api.CreateRaceRequest;
5	import com.example.starter.race.api.RegisterRunnerRequest;
6	import com.example.starter.race.api.SealRaceRequest;
7	import com.example.starter.race.api.StandingResponse;
8	import com.example.starter.race.domain.RaceStatus;
9	import com.example.starter.race.persistence.RaceRow;
10	import com.example.starter.race.support.AbstractRaceH2Test;
11	import com.example.starter.race.support.FixedClockTestConfig;
12	import org.junit.jupiter.api.Test;
13	import org.springframework.beans.factory.annotation.Autowired;
14	import org.springframework.boot.test.context.SpringBootTest;
15	import org.springframework.context.annotation.Import;
16	
17	import java.util.concurrent.CountDownLatch;
18	import java.util.concurrent.ExecutorService;
19	import java.util.concurrent.Executors;
20	import java.util.concurrent.Future;
21	import java.util.concurrent.TimeUnit;
22	import java.util.concurrent.atomic.AtomicInteger;
23	import java.util.stream.IntStream;
24	
25	import static org.assertj.core.api.Assertions.assertThat;
26	
27	/**
28	 * H2 上的真实并发测试：乐观条件 UPDATE 串行化同赛事写操作，
29	 * 封榜与普通写互斥，同 requestId 并发只产生一次业务变更。
30	 */
31	@SpringBootTest
32	@Import(FixedClockTestConfig.class)
33	class RaceConcurrencyH2Test extends AbstractRaceH2Test {
34	
35	    private static final String RACE = "race-concurrent";
36	
37	    @Autowired
38	    private RaceService raceService;
39	
40	    @Test
41	    void 并发同版本登记仅一个成功且版本只加一() throws Exception {
42	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
43	
44	        int threads = 10;
45	        ExecutorService pool = Executors.newFixedThreadPool(threads);
46	        CountDownLatch start = new CountDownLatch(1);
47	        AtomicInteger success = new AtomicInteger();
48	        AtomicInteger conflicts = new AtomicInteger();
49	        try {
50	            var futures = IntStream.range(0, threads)
51	                    .mapToObj(i -> (java.util.concurrent.Callable<Void>) () -> {
52	                        start.await();
53	                        try {
54	                            raceService.registerRunner(RACE, new RegisterRunnerRequest(
55	                                    "bib-" + i, 1000L, 1, "req-reg-" + i));
56	                            success.incrementAndGet();
57	                        } catch (ConflictException ex) {
58	                            conflicts.incrementAndGet();
59	                        }
60	                        return null;
61	                    })
62	                    .map(pool::submit)
63	                    .toList();
64	            start.countDown();
65	            for (Future<Void> future : futures) {
66	                future.get(30, TimeUnit.SECONDS);
67	            }
68	        } finally {
69	            pool.shutdownNow();
70	        }
71	
72	        assertThat(success.get()).isEqualTo(1);
73	        assertThat(conflicts.get()).isEqualTo(threads - 1);
74	        RaceRow race = repository.findRace(RACE).orElseThrow();
75	        assertThat(race.version()).isEqualTo(2);
76	        assertThat(repository.findRunners(RACE)).hasSize(1);
77	    }
78	
79	    @Test
80	    void 封榜与处罚并发时互斥且最终状态自洽() throws Exception {
81	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
82	        raceService.registerRunner(RACE,
83	                new RegisterRunnerRequest("a", 1000L, 1, "req-a"));
84	        // 当前版本为2：封榜与加时都以 expectedVersion=2 并发提交
85	        int runs = 8;
86	        ExecutorService pool = Executors.newFixedThreadPool(runs);
87	        CountDownLatch start = new CountDownLatch(1);
88	        AtomicInteger sealSuccess = new AtomicInteger();
89	        AtomicInteger penaltySuccess = new AtomicInteger();
90	        AtomicInteger conflicts = new AtomicInteger();
91	        try {
92	            var futures = IntStream.range(0, runs)
93	                    .mapToObj(i -> (java.util.concurrent.Callable<Void>) () -> {
94	                        start.await();
95	                        try {
96	                            if (i % 2 == 0) {
97	                                raceService.sealRace(RACE,
98	                                        new SealRaceRequest(2, "req-seal-" + i));
99	                                sealSuccess.incrementAndGet();
100	                            } else {
101	                                raceService.addPenalty(RACE, new AddPenaltyRequest(
102	                                        "pen-" + i, "a", "ADD_TIME", 100L, 2, "req-pen-" + i));
103	                                penaltySuccess.incrementAndGet();
104	                            }
105	                        } catch (ConflictException ex) {
106	                            conflicts.incrementAndGet();
107	                        }
108	                        return null;
109	                    })
110	                    .map(pool::submit)
111	                    .toList();
112	            start.countDown();
113	            for (Future<Void> future : futures) {
114	                future.get(30, TimeUnit.SECONDS);
115	            }
116	        } finally {
117	            pool.shutdownNow();
118	        }
119	
120	        // 两类操作互斥：恰好一类成功一次，其余全部冲突；版本总共只加一
121	        assertThat(sealSuccess.get() + penaltySuccess.get()).isEqualTo(1);
122	        assertThat(conflicts.get()).isEqualTo(runs - 1);
123	        RaceRow race = repository.findRace(RACE).orElseThrow();
124	        assertThat(race.version()).isEqualTo(3);
125	        if (sealSuccess.get() == 1) {
126	            assertThat(race.status()).isEqualTo(RaceStatus.SEALED);
127	            assertThat(repository.findSnapshot(RACE)).isPresent();
128	            // 封榜前无任何处罚成功
129	            assertThat(repository.findPenalties(RACE)).isEmpty();
130	        } else {
131	            assertThat(race.status()).isEqualTo(RaceStatus.OPEN);
132	            assertThat(repository.findSnapshot(RACE)).isEmpty();
133	            assertThat(repository.findPenalties(RACE)).hasSize(1);
134	            StandingResponse standing = raceService.getResults(RACE);
135	            assertThat(standing.entries().getFirst().penaltyMs()).isEqualTo(100L);
136	        }
137	    }
138	
139	    @Test
140	    void 同requestId并发重放只产生一次变更且结果一致() throws Exception {
141	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
142	
143	        int threads = 6;
144	        ExecutorService pool = Executors.newFixedThreadPool(threads);
145	        CountDownLatch start = new CountDownLatch(1);
146	        AtomicInteger success = new AtomicInteger();
147	        AtomicInteger errors = new AtomicInteger();
148	        try {
149	            var futures = IntStream.range(0, threads)
150	                    .mapToObj(i -> (java.util.concurrent.Callable<ServiceResult>) () -> {
151	                        start.await();
152	                        try {
153	                            ServiceResult result = raceService.registerRunner(RACE,
154	                                    new RegisterRunnerRequest("same", 1000L, 1, "req-same"));
155	                            success.incrementAndGet();
156	                            return result;
157	                        } catch (RuntimeException ex) {
158	                            errors.incrementAndGet();
159	                            throw ex;
160	                        }
161	                    })
162	                    .map(pool::submit)
163	                    .toList();
164	            start.countDown();
165	            ServiceResult first = futures.getFirst().get(30, TimeUnit.SECONDS);
166	            for (Future<ServiceResult> future : futures) {
167	                ServiceResult result = future.get(30, TimeUnit.SECONDS);
168	                assertThat(result.status()).isEqualTo(first.status());
169	            }
170	        } finally {
171	            pool.shutdownNow();
172	        }
173	
174	        assertThat(errors.get()).isZero();
175	        assertThat(success.get()).isEqualTo(threads);
176	        assertThat(repository.findRunners(RACE)).hasSize(1);
177	        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(2);
178	    }
179	}
