    /** 中止开始的比赛相对耗时（毫秒）。 */
    long startElapsedMs();

    /** 是否已恢复：false 表示赛事仍处于该事件的 SUSPENDED 状态。 */
    boolean resumed();

    /** 恢复时刻（毫秒）；未恢复时为 0。 */
    long resumeElapsedMs();

    /** 中止时长=resumeElapsedMs-startElapsedMs（毫秒）；未恢复时为 0。 */
    long durationMs();
}

